$$

$$
\frac{\int_{0}^{\epsilon} \exp\left(-\frac{t}{\lambda}\right) \sum_{k=0}^M c^l_k t^{\alpha_k} \, dt}{\int_{\epsilon}^{\infty} \exp\left(-\frac{t}{\lambda}\right) \sum_{k=0}^M c^u_k t^{\alpha_k} \, dt} \geq \delta', \tag{23}
$$

